/**
 * Proactive Coherence Guardian
 * 
 * The component that was architecturally absent: a system that PROACTIVELY
 * evaluates surface coverage, detects changes, and triggers enforcement sweeps
 * when coherence is at risk.
 * 
 * This is not reactive. It doesn't wait for content to be submitted.
 * It asks: "What haven't I seen? What changed? Is coverage complete?"
 */

import { eq, and, sql, inArray, ne } from 'drizzle-orm';
import { getDb } from '../../db';
import { discoveredSurfaces, sweepTriggers, discoveryRuns } from '../../../drizzle/schema';
import { generalLog } from '../../_core/logger';
import { getRepoRoot } from '../../repo-root';
import { notifyOwner } from '../../_core/notification';
import { SurfaceInventoryManager, CoverageScorer } from './inventory';
import { getAdapter, getAllAdapters } from './adapters';
import type {
  DiscoveryConfigData,
  SweepEvaluation,
  SweepResult,
  ChangeDetectionResult,
  DiscoveredSurfaceData,
  AdapterConfig,
  SurfaceType,
  BusinessTruth,
} from './types';
import { DiscoveryStatus } from './types';
import { remediateSweepResults } from './remediation';
import { gatedRemediateSweepResults } from './gravito-gate';
import { evaluateCompletenessGate } from './completeness-gate';
import { getBusinessTruthContext } from '../../services/truth-context-provider';

const log = generalLog.child({ module: 'proactive-coherence-guardian' });

// =============================================================================
// DISCOVERY ORCHESTRATOR
// =============================================================================

/**
 * Run discovery across all configured adapters for a customer.
 * This is the entry point for proactive surface discovery.
 */
export async function runDiscovery(customerId: string, config: DiscoveryConfigData): Promise<{
  runId: string;
  totalDiscovered: number;
  newSurfaces: number;
  staleSurfaces: number;
  deadSurfaces: number;
  adapterResults: Array<{ adapter: string; surfacesFound: number; durationMs: number; error?: string }>;
}> {
  const db = await getDb();
  if (!db) throw new Error('Database unavailable');

  const runId = `discovery_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const startTime = Date.now();
  const inventoryManager = new SurfaceInventoryManager();
  const adapterResults: Array<{ adapter: string; surfacesFound: number; durationMs: number; error?: string }> = [];
  let allDiscovered: DiscoveredSurfaceData[] = [];

  log.info({ customerId, runId, adapters: config.adapters.length }, 'Starting discovery run');

  // Record the run
  await db.insert(discoveryRuns).values({
    runId,
    customerId,
    adapterType: config.adapters.map(a => a.type).join(','),
    status: 'running',
    startedAt: new Date(startTime),
  });

  // Run each enabled adapter
  for (const adapterConfig of config.adapters) {
    if (!adapterConfig.enabled) continue;

    const adapter = getAdapter(adapterConfig.type);
    if (!adapter) {
      log.error({ adapterType: adapterConfig.type, customerId }, 'COVERAGE GAP: Configured adapter not registered — surfaces of this type will NOT be discovered. Register the adapter or remove from config.');
      adapterResults.push({ adapter: adapterConfig.type, surfacesFound: 0, durationMs: 0, error: 'COVERAGE GAP: Adapter not registered' });
      // Notify owner about the coverage gap
      await notifyOwner({
        title: `Surface Discovery: COVERAGE GAP — adapter "${adapterConfig.type}" not registered`,
        content: `Customer ${customerId} has adapter "${adapterConfig.type}" configured but it is not registered in the system. Surfaces of this type will NOT be discovered, creating a silent coverage gap. Register the adapter or remove it from the customer config.`,
      }).catch(() => {});
      continue;
    }

    const adapterStart = Date.now();
    try {
      // Validate config first
      const validation = await adapter.validateConfig(adapterConfig);
      if (!validation.valid) {
        log.warn({ adapterType: adapterConfig.type, errors: validation.errors }, 'Invalid adapter config');
        adapterResults.push({
          adapter: adapterConfig.type,
          surfacesFound: 0,
          durationMs: Date.now() - adapterStart,
          error: `Invalid config: ${validation.errors?.join(', ')}`,
        });
        continue;
      }

      // Run discovery
      const discovered = await adapter.discover(customerId, adapterConfig);
      allDiscovered = allDiscovered.concat(discovered);

      adapterResults.push({
        adapter: adapterConfig.type,
        surfacesFound: discovered.length,
        durationMs: Date.now() - adapterStart,
      });
    } catch (error) {
      const errMsg = error instanceof Error ? error.message : String(error);
      log.error({ adapterType: adapterConfig.type, error: errMsg }, 'Adapter discovery failed');
      adapterResults.push({
        adapter: adapterConfig.type,
        surfacesFound: 0,
        durationMs: Date.now() - adapterStart,
        error: errMsg,
      });
    }
  }

  // Update inventory with all discovered surfaces
  const inventoryResult = await inventoryManager.updateInventory(customerId, allDiscovered);

  // Apply exclusion patterns
  if (config.exclusionPatterns.length > 0) {
    for (const pattern of config.exclusionPatterns) {
      try {
        const regex = new RegExp(pattern, 'i');
        const toIgnore = allDiscovered.filter(s => regex.test(s.url) || (s.title && regex.test(s.title)));
        for (const surface of toIgnore) {
          await db.update(discoveredSurfaces)
            .set({ status: 'ignored' })
            .where(
              and(
                eq(discoveredSurfaces.surfaceId, surface.surfaceId),
                eq(discoveredSurfaces.customerId, customerId),
              )
            );
        }
      } catch {
        log.warn({ pattern }, 'Invalid exclusion pattern');
      }
    }
  }

  // Update the run record
  const durationMs = Date.now() - startTime;
  await db.update(discoveryRuns)
    .set({
      status: 'completed',
      surfacesDiscovered: allDiscovered.length,
      surfacesNew: inventoryResult.newSurfaces,
      surfacesStale: inventoryResult.staleSurfaces,
      surfacesDead: inventoryResult.deadSurfaces,
      durationMs,
      completedAt: new Date(),
    })
    .where(eq(discoveryRuns.runId, runId));

  log.info({
    customerId, runId, durationMs,
    totalDiscovered: allDiscovered.length,
    new: inventoryResult.newSurfaces,
    stale: inventoryResult.staleSurfaces,
    dead: inventoryResult.deadSurfaces,
  }, 'Discovery run complete');

  return {
    runId,
    totalDiscovered: allDiscovered.length,
    newSurfaces: inventoryResult.newSurfaces,
    staleSurfaces: inventoryResult.staleSurfaces,
    deadSurfaces: inventoryResult.deadSurfaces,
    adapterResults,
  };
}

// =============================================================================
// CHANGE DETECTOR
// =============================================================================

/**
 * Detect changes across all known surfaces for a customer.
 * Verifies each surface against its adapter to find stale/dead content.
 */
export async function detectChanges(customerId: string): Promise<ChangeDetectionResult> {
  const db = await getDb();
  if (!db) throw new Error('Database unavailable');

  const startTime = Date.now();
  const inventoryManager = new SurfaceInventoryManager();
  const inventory = await inventoryManager.getInventory(customerId);

  const changedSurfaces: ChangeDetectionResult['changedSurfaces'] = [];
  const deadSurfaces: ChangeDetectionResult['deadSurfaces'] = [];

  // Only check active surfaces (not dead/ignored)
  const activeSurfaces = inventory.filter(s => s.status !== 'dead' && s.status !== 'ignored');

  for (const entry of activeSurfaces) {
    const adapter = getAdapter(entry.discoverySource);
    if (!adapter) continue;

    try {
      const verification = await adapter.verify({
        surfaceId: entry.surfaceId,
        url: entry.url,
        surfaceType: entry.surfaceType as SurfaceType,
        contentHash: entry.contentHash,
        lastSeen: entry.lastSeen,
        metadata: (entry.metadata as unknown as Record<string, unknown>) || {},
        discoverySource: entry.discoverySource,
      });

      if (!verification.exists) {
        deadSurfaces.push({
          surfaceId: entry.surfaceId,
          url: entry.url,
          lastSeen: entry.lastSeen,
        });
        await db.update(discoveredSurfaces)
          .set({ status: 'dead' })
          .where(eq(discoveredSurfaces.id, entry.id));
      } else if (verification.contentHash && verification.contentHash !== entry.contentHash) {
        changedSurfaces.push({
          surfaceId: entry.surfaceId,
          oldHash: entry.contentHash,
          newHash: verification.contentHash,
        });
        await db.update(discoveredSurfaces)
          .set({
            contentHash: verification.contentHash,
            contentSnapshot: verification.contentSnapshot || entry.contentSnapshot,
            status: entry.status === 'reviewed' ? 'stale' : entry.status,
            lastSeen: new Date(),
          })
          .where(eq(discoveredSurfaces.id, entry.id));
      }
    } catch (error) {
      log.debug({ surfaceId: entry.surfaceId, error: error instanceof Error ? error.message : String(error) }, 'Verification error');
    }
  }

  return {
    changedSurfaces,
    newSurfaces: [], // New surfaces are found during discovery, not change detection
    deadSurfaces,
    totalChecked: activeSurfaces.length,
    durationMs: Date.now() - startTime,
  };
}

// =============================================================================
// SWEEP EVALUATOR & TRIGGER
// =============================================================================

/**
 * Evaluate whether a coverage sweep should be triggered.
 * This is the completeness gate — the thing that asks "have we seen everything?"
 */
export async function evaluateForSweep(customerId: string, config?: DiscoveryConfigData): Promise<SweepEvaluation> {
  const coverageScorer = new CoverageScorer();
  const coverage = await coverageScorer.computeCoverage(customerId);

  const thresholds = config?.coverageThresholds || {
    sweepTrigger: 0.8,
    criticalThreshold: 0.5,
    staleThresholdDays: 30,
  };

  const reasons: string[] = [];
  let shouldTrigger = false;

  // Reason 1: Coverage is below the sweep trigger threshold
  if (coverage.overallCoverage < thresholds.sweepTrigger) {
    shouldTrigger = true;
    reasons.push(`Coverage (${(coverage.overallCoverage * 100).toFixed(1)}%) is below the trigger threshold of ${(thresholds.sweepTrigger * 100).toFixed(1)}%`);
  }

  // Reason 2: Coverage is critically low
  if (coverage.overallCoverage < thresholds.criticalThreshold) {
    shouldTrigger = true;
    reasons.push(`CRITICAL: Coverage (${(coverage.overallCoverage * 100).toFixed(1)}%) is below the critical threshold of ${(thresholds.criticalThreshold * 100).toFixed(1)}%`);
  }

  // Reason 3: Stale surfaces exist
  if (coverage.staleSurfaces > 0) {
    shouldTrigger = true;
    reasons.push(`${coverage.staleSurfaces} surfaces are stale (not reviewed recently)`);
  }

  // Reason 4: New, unreviewed surfaces exist.
  // CoverageReportData has no newCount field; the count of surfaces awaiting
  // review is derived from the ones it does carry — everything that is not
  // reviewed, stale, dead or ignored.
  const newSurfaceCount = Math.max(
    0,
    coverage.totalSurfaces
      - coverage.reviewedSurfaces
      - coverage.staleSurfaces
      - coverage.deadSurfaces
      - coverage.ignoredSurfaces,
  );
  if (newSurfaceCount > 0) {
    shouldTrigger = true;
    reasons.push(`${newSurfaceCount} new surfaces are awaiting review`);
  }

  // Determine priority
  const priority = coverage.overallCoverage < thresholds.criticalThreshold ? 'critical' : 'medium';

  const affectedSurfaces = shouldTrigger ? (await getDb().select().from(discoveredSurfaces).where(and(eq(discoveredSurfaces.customerId, customerId), ne(discoveredSurfaces.status, 'ignored')))).map(s => s.surfaceId) : [];

  return {
    shouldTrigger,
    reasons,
    priority,
    coverageAtEvaluation: coverage.overallCoverage,
    affectedSurfaces,
  };
}

/**
 * Trigger a sweep run and store it in the database.
 */
export async function triggerSweep(customerId: string, evaluation: SweepEvaluation, triggerType: 'manual' | 'scheduled'): Promise<SweepResult> {
  const db = await getDb();
  if (!db) throw new Error('Database unavailable');

  const sweepId = `sweep_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const startTime = Date.now();

  // Store the trigger record
  await db.insert(sweepTriggers).values({
    sweepId,
    customerId,
    triggerType,
    status: 'triggered',
    triggeredAt: new Date(),
    evaluation: JSON.stringify(evaluation),
    priority: evaluation.priority,
  });

  log.info({ customerId, sweepId, triggerType, priority: evaluation.priority }, 'Sweep triggered, starting remediation...');

  // Get all active surfaces for the customer
  const surfacesToSweep = await db.select().from(discoveredSurfaces).where(
    and(
      eq(discoveredSurfaces.customerId, customerId),
      inArray(discoveredSurfaces.status, ['new', 'stale', 'reviewed'])
    )
  );

  if (surfacesToSweep.length === 0) {
    log.warn({ customerId, sweepId }, 'Sweep triggered but no active surfaces found to process.');
    const result: SweepResult = { sweepId, status: 'completed', surfacesProcessed: 0, durationMs: Date.now() - startTime, errors: [] };
    await db.update(sweepTriggers).set({ status: 'completed', result: JSON.stringify(result) }).where(eq(sweepTriggers.sweepId, sweepId));
    return result;
  }

  // Map to Shield-compatible format
  const shieldInputs = surfacesToSweep.map(surface => ({
    surface_id: surface.surfaceId,
    customer_id: customerId,
    surface_type: mapSurfaceTypeToShieldType(surface.surfaceType),
    content_url: surface.url,
    content_snapshot: surface.contentSnapshot || '',
  }));

  // Get business truth context
  const truthContext = await getBusinessTruthContext(customerId) as BusinessTruth;

  // Execute remediation via Shield
  let shieldResults: Awaited<ReturnType<typeof remediateSweepResults>>;
  try {
    // Use the gated function to ensure Gravito review
    const remediationInput = shieldResults.map(r => ({ ...r, truthContext }));
    shieldResults = await gatedRemediateSweepResults(remediationInput);

  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error({ customerId, sweepId, error: errMsg }, 'Remediation sweep failed');
    const result: SweepResult = { sweepId, status: 'failed', surfacesProcessed: 0, durationMs: Date.now() - startTime, errors: [errMsg] };
    await db.update(sweepTriggers).set({ status: 'failed', result: JSON.stringify(result) }).where(eq(sweepTriggers.sweepId, sweepId));
    return result;
  }

  // Post-process results (e.g., update surface status)
  const errors: string[] = [];
  for (const res of shieldResults) {
    if (res.status === 'error') {
      errors.push(`Surface ${res.surface_id}: ${res.error}`);
      continue;
    }
    await db.update(discoveredSurfaces)
      .set({ status: 'reviewed', lastSeen: new Date() })
      .where(and(eq(discoveredSurfaces.surfaceId, res.surface_id), eq(discoveredSurfaces.customerId, customerId)));
  }

  const result: SweepResult = {
    sweepId,
    status: errors.length > 0 ? 'completed_with_errors' : 'completed',
    surfacesProcessed: shieldInputs.length,
    durationMs: Date.now() - startTime,
    errors,
  };

  await db.update(sweepTriggers).set({ status: result.status, result: JSON.stringify(result) }).where(eq(sweepTriggers.sweepId, sweepId));

  log.info({ customerId, sweepId, duration: result.durationMs, processed: result.surfacesProcessed, errors: errors.length }, 'Remediation sweep complete');

  return result;
}


// =============================================================================
// FULL PIPELINE ORCHESTRATOR
// =============================================================================

/**
 * Run the complete proactive coherence pipeline:
 * 1. Discover all surfaces
 * 2. Detect changes in known surfaces
 * 3. Compute coverage
 * 4. Evaluate for sweep
 * 5. Trigger sweep if needed
 * 
 * This is what should run on a cron schedule.
 */
export async function runProactiveCoherencePipeline(customerId: string, config: DiscoveryConfigData): Promise<{
  discovery: Awaited<ReturnType<typeof runDiscovery>>;
  changes: ChangeDetectionResult;
  evaluation: SweepEvaluation;
  sweep?: SweepResult;
}> {
  log.info({ customerId }, 'Starting proactive coherence pipeline');

  // Step 1: Discover
  const discovery = await runDiscovery(customerId, config);

  // Step 2: Detect changes
  const changes = await detectChanges(customerId);

  // Step 3: Evaluate coverage
  const evaluation = await evaluateForSweep(customerId, config);

  // Step 4: Trigger sweep if needed
  let sweep: SweepResult | undefined;
  if (evaluation.shouldTrigger) {
    log.info({
      customerId,
      priority: evaluation.priority,
      reasons: evaluation.reasons,
      affectedSurfaces: evaluation.affectedSurfaces,
    }, 'Sweep triggered');

    sweep = await triggerSweep(customerId, evaluation, 'scheduled');
  } else {
    log.info({ customerId, coverage: evaluation.coverageAtEvaluation }, 'No sweep needed — coverage acceptable');
  }

  // Step 5: Evaluate completeness gate
  const gateResult = await evaluateCompletenessGate(customerId);
  log.info({
    customerId,
    gateStatus: gateResult.gateStatus,
    coverage: gateResult.coverageAtEvaluation,
    blockReasons: gateResult.blockReasons,
  }, 'Completeness gate evaluated');

  if (gateResult.gateStatus === 'blocked') {
    log.warn({
      customerId,
      blockReasons: gateResult.blockReasons,
    }, 'COMPLETENESS GATE BLOCKED after pipeline — coherence cannot be confirmed');
  }

  return { discovery, changes, evaluation, sweep };
}

// =============================================================================
// HELPERS
// =============================================================================

function mapSurfaceTypeToShieldType(surfaceType: string): string {
  const mapping: Record<string, string> = {
    web_page: 'website',
    api_endpoint: 'generic',
    email_template: 'sales',
    chat_config: 'support',
    code_component: 'website',
    documentation: 'generic',
    mobile_screen: 'website',
    social_post: 'sales',
    ad_copy: 'sales',
    slide_deck: 'sales',
    other: 'generic',
  };
  return mapping[surfaceType] || 'generic';
}

/**
 * Get the default discovery config for Gravito's own surfaces (dogfooding).
 */
export function getDefaultDogfoodConfig(customerId: string): DiscoveryConfigData {
  return {
    customerId,
    adapters: [
      {
        type: 'code_scanner',
        enabled: true,
        config: {
          rootPath: getRepoRoot(),
          framework: 'react',
        } as unknown as Record<string, unknown>,
      },
      {
        type: 'documentation',
        enabled: true,
        config: {
          rootPath: getRepoRoot(),
        } as unknown as Record<string, unknown>,
      },
    ],
    coverageThresholds: {
      sweepTrigger: 0.8,
      criticalThreshold: 0.5,
      staleThresholdDays: 7,
    },
    exclusionPatterns: [
      'node_modules',
      '\\.test\\.',
      '_core',
      'DashboardLayoutSkeleton',
    ],
  };
}

