// =============================================================================
// BATCH REMEDIATION (for sweeps)
// =============================================================================

/**
 * Remediate all surfaces from a sweep that had issues.
 * This is called by the guardian after triggerSweep finds incoherent surfaces.
 */
export async function remediateSweepResults(
  sweepId: number,
  customerId: string,
  surfaceResults: Array<{
    surfaceId: string;
    surfaceUrl: string;
    content: string;
    reviewResult: {
      score: number;
      issues: any[];
      patches: any[];
      block_release: boolean;
    };
  }>,
  truthContext?: string,
): Promise<{
  totalSurfaces: number;
  autoRewritten: number;
  patchesApplied: number;
  flaggedForReview: number;
  manualRequired: number;
  skipped: number;
  results: RemediationOutput[];
}> {
  log.info({
    sweepId, customerId,
    surfaceCount: surfaceResults.length,
  }, 'Starting batch remediation');

  const results: RemediationOutput[] = [];
  let autoRewritten = 0;
  let patchesApplied = 0;
  let flaggedForReview = 0;
  let manualRequired = 0;
  let skipped = 0;

  for (const surface of surfaceResults) {
    try {
      const result = await remediateSurface(sweepId, customerId, {
        surfaceId: surface.surfaceId,
        surfaceUrl: surface.surfaceUrl,
        content: surface.content,
        issues: surface.reviewResult.issues,
        patches: surface.reviewResult.patches,
        score: surface.reviewResult.score,
        truthContext,
      });

      results.push(result);

      switch (result.actionType) {
        case 'auto_rewrite': autoRewritten++; break;
        case 'patch_applied': patchesApplied++; break;
        case 'flagged_for_review': flaggedForReview++; break;
        case 'manual_required': manualRequired++; break;
        case 'skipped': skipped++; break;
      }
    } catch (error) {
      log.error({
        surfaceId: surface.surfaceId,
        error: error instanceof Error ? error.message : String(error),
      }, 'Failed to remediate surface');
      skipped++;
    }
  }

  // Notify owner with summary
  if (autoRewritten > 0 || patchesApplied > 0 || flaggedForReview > 0) {
    await notifyOwner({
      title: `Auto-Remediation Complete: ${autoRewritten + patchesApplied} surfaces fixed`,
      content: [
        `Sweep #${sweepId} remediation results:`,
        `- Auto-rewritten: ${autoRewritten}`,
        `- Patches applied: ${patchesApplied}`,
        `- Flagged for review: ${flaggedForReview}`,
        `- Manual required: ${manualRequired}`,
        `- Skipped: ${skipped}`,
        '',
        flaggedForReview > 0 ? `⚠️ ${flaggedForReview} surfaces need human review.` : '',
      ].filter(Boolean).join('\n'),
    }).catch(() => {});
  }

  log.info({
    sweepId, customerId,
    autoRewritten, patchesApplied, flaggedForReview, manualRequired, skipped,
  }, 'Batch remediation complete');

  return {
    totalSurfaces: surfaceResults.length,
    autoRewritten,
    patchesApplied,
    flaggedForReview,
    manualRequired,
    skipped,
    results,
  };

