 * This replaces remediateSweepResults in the guardian pipeline.
 */
export async function gatedRemediateSweepResults(
  sweepId: number,
  customerId: string,
  surfaceResults: Array<{
    surfaceId: string;
    surfaceUrl: string;
    content: string;
    reviewResult: {
      score: number;
      issues: any[];
      patches: any[];
      block_release: boolean;
    };
  }>,
  truthContext?: string,
  config: Partial<GateConfig> = {},
): Promise<{
  totalSurfaces: number;
  accepted: number;
  blocked: number;
  blockedUnavailable: number;
  passedWithWarnings: number;
  results: Array<{
    surfaceId: string;
    accepted: boolean;
    gateDecision: GateDecision;
    gravitoRunId: string | null;
    attempts: number;
  }>;
}> {
  log.info({
    sweepId, customerId,
    surfaceCount: surfaceResults.length,
  }, 'Starting batch gated remediation');

  let accepted = 0;
  let blocked = 0;
  let blockedUnavailable = 0;
  let passedWithWarnings = 0;
  const results: Array<{
    surfaceId: string;
    accepted: boolean;
    gateDecision: GateDecision;
    gravitoRunId: string | null;
    attempts: number;
  }> = [];

  for (const surface of surfaceResults) {
    try {
      const result = await gatedRemediation(sweepId, customerId, {
        surfaceId: surface.surfaceId,
        surfaceUrl: surface.surfaceUrl,
        content: surface.content,
        issues: surface.reviewResult.issues,
        patches: surface.reviewResult.patches,
        score: surface.reviewResult.score,
        truthContext,
      }, config);

      results.push({
        surfaceId: surface.surfaceId,
        accepted: result.accepted,
        gateDecision: result.gateDecision,
        gravitoRunId: result.gravitoRunId,
        attempts: result.attempts,
      });

      switch (result.gateDecision) {
        case 'passed': accepted++; break;
        case 'passed_with_warnings': passedWithWarnings++; accepted++; break;
        case 'blocked': blocked++; break;
        case 'blocked_unavailable': blockedUnavailable++; break;
      }
    } catch (error) {
      log.error({
        surfaceId: surface.surfaceId,
        error: error instanceof Error ? error.message : String(error),
      }, 'Gated remediation failed for surface');
      blocked++;
      results.push({
        surfaceId: surface.surfaceId,
        accepted: false,
        gateDecision: 'blocked',
        gravitoRunId: null,
        attempts: 0,
      });
    }
  }

  // Summary notification
  if (surfaceResults.length > 0) {
    await notifyOwner({
      title: `Gravito-Gated Remediation: ${accepted}/${surfaceResults.length} accepted`,
      content: [
        `Sweep #${sweepId} gated remediation results:`,
        `- Accepted (passed): ${accepted - passedWithWarnings}`,
