        `- Blocked (issues): ${blocked}`,
        `- Blocked (Gravito unavailable): ${blockedUnavailable}`,
        '',
        blocked > 0 ? `⚠️ ${blocked} surfaces blocked — require human review.` : '✅ All surfaces passed the Gravito gate.',
        blockedUnavailable > 0 ? `🔴 ${blockedUnavailable} surfaces blocked due to Gravito unavailability (fail-closed).` : '',
      ].filter(Boolean).join('\n'),
    }).catch(() => {});
  }

  log.info({
    sweepId, customerId,
    total: surfaceResults.length,
    accepted, blocked, blockedUnavailable, passedWithWarnings,
  }, 'Batch gated remediation complete');

  return {
    totalSurfaces: surfaceResults.length,
    accepted,
    blocked,
    blockedUnavailable,
    passedWithWarnings,
    results,
  };

