async function reviewRewriteWithGravito(proposedContent: string, violationType: string): Promise<{
  gravito_run_id: string | null;
  score: number;
  block_release: boolean;
  issues: string[];
} | null> {
  try {
    const result = await callGravitoTool('reviewContent', {
      content: proposedContent,
      surface_type: 'website',
      artifact_type: 'web_copy',
      context: `Post-rewrite review for ${violationType} fix`,
    }, { caller: 'auto-rewrite-pipeline', timeoutMs: 15000 });

    if (result.success && result.result) {
      const r = result.result as unknown;
      return {
        gravito_run_id: result.gravito_run_id || null,
        score: r.score || 0,
        block_release: r.block_release || false,
        issues: (r.issues || []).map((i: any) => typeof i === 'string' ? i : i.message || JSON.stringify(i)),
      };
    }

    // If Gravito returned infra_degraded, log but don't block
    if (result.classification === 'infra_degraded') {
      generalLog.info('[AutoRewrite] reviewContent infra_degraded — continuing without post-review');
      return null;
    }

    return null;
  } catch (error) {
    generalLog.warn('[AutoRewrite] Gravito reviewContent failed, continuing without post-review:', error);
    return null;
  }
}

