200	 * Remediate a surface WITH the mandatory Gravito gate.
201	 * 
202	 * Flow:
203	 * 1. Claude generates remediated content
204	 * 2. Gravito Gate evaluates the output
205	 * 3. If PASSED: content is accepted
206	 * 4. If BLOCKED: re-remediate using Gravito's feedback, then re-gate
207	 * 5. If still BLOCKED: flag for human review
208	 * 
209	 * This is the function that should replace direct calls to remediateSurface.
210	 */
211	export async function gatedRemediation(
212	  sweepId: number,
213	  customerId: string,
214	  input: {
215	    surfaceId: string;
216	    surfaceUrl: string;
217	    content: string;
218	    issues: any[];
219	    patches: any[];
220	    score: number;
221	    truthContext?: string;
222	  },
223	  config: Partial<GateConfig> = {},
224	): Promise<{
225	  accepted: boolean;
226	  gateDecision: GateDecision;
