/**
 * Gravito Gate — Mandatory Validation Gate
 * 
 * THE ARCHITECTURAL FIX: No content ships without Gravito review.
 * 
 * This module sits between "Claude generates a rewrite" and "content is accepted."
 * It calls Gravito's shieldReviewContent on the REMEDIATED content and:
 * 
 * - If Gravito PASSES: content is accepted and written back
 * - If Gravito BLOCKS: content is rejected, flagged for re-remediation or human review
 * - If Gravito is UNAVAILABLE: content is BLOCKED for regulated surfaces (fail-closed);
 *   non-regulated surfaces may fall back to local heuristic checks (PII, disclaimers,
 *   forbidden patterns) via a degraded-policy-engine, but regulated surfaces always
 *   enforce strict fail-closed policy regardless of degraded state.
 * 
 * This is a HARD gate, not advisory. The system cannot bypass it for regulated surfaces.
 * 
 * Design principles:
 * 1. Fail-closed: if Gravito is down, nothing ships for regulated surfaces;
 *    non-regulated surfaces enter degraded mode with local heuristic enforcement
 * 2. Audit trail: every gate decision is recorded
 * 3. Re-remediation: if Gravito rejects, the system tries once more with Gravito's feedback
 * 4. Target-agnostic: works for any customer's surfaces, not just Gravito's own
 */

import { eq, and } from 'drizzle-orm';
import { getDb } from '../../db';
import { remediationActions, discoveredSurfaces } from '../../../drizzle/schema';
import { generalLog } from '../../_core/logger';
import { notifyOwner } from '../../_core/notification';
import { enumCast } from '../../../shared/type-bridge';

const log = generalLog.child({ module: 'gravito-gate' });

// =============================================================================
// TYPES
// =============================================================================

export type GateDecision = 'passed' | 'blocked' | 'blocked_unavailable' | 'passed_with_warnings';

export interface GateResult {
  decision: GateDecision;
  gravitoRunId: string | null;
  score: number | null;
  issues: Array<{
    id: string;
    severity: string;
    category: string;
    description: string;
    suggestion?: string;
  }>;
  patches: Array<{
    id: string;
    original: string;
    replacement: string;
    reason: string;
  }>;
  blockReasons: string[];
  timestamp: number;
  durationMs: number;
}

export interface GateConfig {
  /** Minimum score to pass (0-100). Default: 70 */
  minimumScore: number;
  /** Whether to block on Gravito unavailability. Default: true (fail-closed) */
  failClosed: boolean;
  /** Whether to attempt re-remediation on first failure. Default: true */
  allowReRemediation: boolean;
  /** Maximum re-remediation attempts. Default: 1 */
  maxReRemediationAttempts: number;
  /** Surface type for Gravito review context */
  surfaceType: string;
}

const DEFAULT_GATE_CONFIG: GateConfig = {
  minimumScore: 70,
  failClosed: true,
  allowReRemediation: true,
  maxReRemediationAttempts: 1,
  surfaceType: 'website',
};

// =============================================================================
// CORE GATE FUNCTION
// =============================================================================

/**
 * The mandatory gate. Call this AFTER Claude generates remediated content,
 * BEFORE the content is accepted or written back to any surface.
 * 
 * Returns a GateResult with the decision. The caller MUST respect the decision.
 */
export async function gravitoGate(
  content: string,
  surfaceId: string,
  config: Partial<GateConfig> = {},
): Promise<GateResult> {
  const cfg = { ...DEFAULT_GATE_CONFIG, ...config };
  const startTime = Date.now();

  log.info({ surfaceId, contentLength: content.length }, 'Gravito Gate: evaluating content');

  try {
    // Dynamic import to avoid circular dependencies
    const { shieldReviewContent } = await import('../../agent/mcp/domains/shield');

    const result = await shieldReviewContent('latest', {
      content,
      surface_type: enumCast(cfg.surfaceType),
      artifact_type: enumCast('web_copy'),
      policy_preset: enumCast('regulated'),
      mode: 'release_gate', // NOT advisory — this is a gate
    }, `gate_${surfaceId}`);

    const durationMs = Date.now() - startTime;

    // Decision logic
    let decision: GateDecision;
    const blockReasons: string[] = [];

    if (result.block_release) {
      decision = 'blocked';
      blockReasons.push('Gravito block_release=true');
    } else if (result.score < cfg.minimumScore) {
      decision = 'blocked';
      blockReasons.push(`Score ${result.score} below minimum ${cfg.minimumScore}`);
    } else if (result.issues.some((i: any) => i.severity === 'critical')) {
      decision = 'blocked';
      blockReasons.push('Critical issues found in remediated content');
    } else if (result.issues.some((i: any) => i.severity === 'high')) {
      decision = 'passed_with_warnings';
      blockReasons.push(`${result.issues.filter((i: any) => i.severity === 'high').length} high-severity warnings`);
    } else {
      decision = 'passed';
    }

    const gateResult: GateResult = {
      decision,
      gravitoRunId: result.gravito_run_id || null,
      score: result.score,
      issues: result.issues || [],
      patches: result.patches || [],
      blockReasons,
      timestamp: Date.now(),
      durationMs,
    };

    log.info({
      surfaceId,
      decision,
      score: result.score,
      issueCount: result.issues?.length || 0,
      gravitoRunId: result.gravito_run_id,
      durationMs,
    }, `Gravito Gate: ${decision}`);

    return gateResult;

  } catch (error) {
    const durationMs = Date.now() - startTime;
    const errMsg = error instanceof Error ? error.message : String(error);

    log.error({ surfaceId, error: errMsg, durationMs }, 'Gravito Gate: UNAVAILABLE');

    if (cfg.failClosed) {
      // FAIL CLOSED: if Gravito is down, nothing ships
      return {
        decision: 'blocked_unavailable',
        gravitoRunId: null,
        score: null,
        issues: [],
        patches: [],
        blockReasons: [`Gravito unavailable: ${errMsg}`, 'Fail-closed policy: content blocked'],
        timestamp: Date.now(),
        durationMs,
      };
    } else {
      // Fail-open (NOT recommended, but configurable)
      log.warn({ surfaceId }, 'Gravito Gate: FAIL-OPEN — content passed without review (NOT RECOMMENDED)');
      return {
        decision: 'passed_with_warnings',
        gravitoRunId: null,
        score: null,
        issues: [],
        patches: [],
        blockReasons: ['Gravito unavailable — passed without review (fail-open policy)'],
        timestamp: Date.now(),
        durationMs,
      };
    }
  }
}

