function contentHash(content: string): string {
  // Simple hash for cache key differentiation
  let hash = 0;
  for (let i = 0; i < Math.min(content.length, 500); i++) {
    hash = ((hash << 5) - hash) + content.charCodeAt(i);
    hash |= 0;
  }
  return hash.toString(36);
}
