export const ReviewModeSchema = z.enum([
  'suggest',      // Provide suggestions, don't block
  'release_gate', // Block release if issues found
  'quick',        // Fast path: deterministic checks only (no cross-surface, no experience analyzers, no cognitive loop)
]);
export type ReviewMode = z.infer<typeof ReviewModeSchema>;

// Claim categories for verification
export const ClaimCategorySchema = z.enum([
  'roi',
  'accuracy',
  'security',
  'compliance',
  'performance',
  'availability',
  'other',
]);
export type ClaimCategory = z.infer<typeof ClaimCategorySchema>;

