// ============================================================================

export const ReviewContentInputSchema = z.object({
  surface_type: SurfaceTypeSchema,
  artifact_type: ArtifactTypeSchema,
  content: z.string().min(1),
  policy_preset: PolicyPresetSchema.default('startup'),
  mode: ReviewModeSchema.default('release_gate'),
