export async function triggerSweep(customerId: string, evaluation: SweepEvaluation, triggerType: SweepTriggerType): Promise<SweepResult> {
  const db = await getDb();
  if (!db) throw new Error('Database unavailable');

  const startTime = Date.now();

  // Store the trigger record. `sweep_triggers.id` is the sweep identifier —
  // remediation and gate records key off it, so take it from the insert.
  const [trigger] = await db.insert(sweepTriggers).values({
    customerId,
    triggerType,
    priority: evaluation.priority,
    reasons: evaluation.reasons,
    affectedSurfaces: evaluation.affectedSurfaces,
    coverageAtTrigger: evaluation.coverageAtEvaluation,
    status: 'triggered',
  }).returning({ id: sweepTriggers.id });

  if (!trigger) throw new Error('Failed to record sweep trigger');
  const sweepId = trigger.id;

  log.info({ customerId, sweepId, triggerType, priority: evaluation.priority }, 'Sweep triggered, starting remediation...');

  // Get all active surfaces for the customer
  const surfacesToSweep = await db.select().from(discoveredSurfaces).where(
    and(
      eq(discoveredSurfaces.customerId, customerId),
      inArray(discoveredSurfaces.status, ['new', 'stale', 'reviewed'])
    )
  );

  if (surfacesToSweep.length === 0) {
    log.warn({ customerId, sweepId }, 'Sweep triggered but no active surfaces found to process.');
    const result: SweepResult = {
      sweepId,
      surfacesReviewed: 0,
      surfacesRemediated: 0,
      issuesFound: 0,
      durationMs: Date.now() - startTime,
    };
    await db.update(sweepTriggers)
      .set({ status: 'completed', durationMs: result.durationMs, completedAt: new Date() })
      .where(eq(sweepTriggers.id, sweepId));
    return result;
  }

  // Business truth context is shared by every remediation in this sweep.
  const truthContext = getBusinessTruthContext();

  let issuesFound = 0;
  let gateOutcome: Awaited<ReturnType<typeof gatedRemediateSweepResults>>;
  try {
    // Review each surface through Shield to get the issues/patches that drive remediation.
    // Dynamic import keeps the guardian free of a static dependency on the MCP server.
    const { shieldReviewContent } = await import('../../agent/mcp/domains/shield');

    const remediationInputs: Array<{
      surfaceId: string;
      surfaceUrl: string;
      content: string;
      reviewResult: {
        score: number;
        issues: unknown[];
        patches: unknown[];
        block_release: boolean;
      };
    }> = [];

    for (const surface of surfacesToSweep) {
      const content = surface.contentSnapshot || '';
      if (!content) {
        log.debug({ surfaceId: surface.surfaceId }, 'Skipping surface with no captured content');
        continue;
      }

      const review = await shieldReviewContent('latest', {
        content,
        surface_type: mapSurfaceTypeToShieldType(surface.surfaceType),
        artifact_type: 'web_copy',
        policy_preset: 'regulated',
        mode: 'release_gate',
      }, surface.surfaceId);

      issuesFound += review.issues.length;

      remediationInputs.push({
        surfaceId: surface.surfaceId,
        surfaceUrl: surface.url,
        content,
        reviewResult: {
          score: review.score,
          issues: review.issues,
          patches: review.patches,
          block_release: review.block_release,
        },
      });
    }

    // Use the gated function to ensure Gravito review of every remediation
    gateOutcome = await gatedRemediateSweepResults(sweepId, customerId, remediationInputs, truthContext);

  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error({ customerId, sweepId, error: errMsg }, 'Remediation sweep failed');
    const result: SweepResult = {
      sweepId,
      surfacesReviewed: 0,
      surfacesRemediated: 0,
      issuesFound,
      durationMs: Date.now() - startTime,
    };
    await db.update(sweepTriggers)
      .set({ status: 'failed', durationMs: result.durationMs, completedAt: new Date() })
      .where(eq(sweepTriggers.id, sweepId));
    return result;
  }

  // Post-process results: only surfaces whose remediation cleared the gate are marked reviewed.
  const blocked: string[] = [];
  for (const res of gateOutcome.results) {
    if (!res.accepted) {
      blocked.push(res.surfaceId);
      continue;
    }
    await db.update(discoveredSurfaces)
      .set({ status: 'reviewed', lastReviewedAt: new Date(), lastSeen: new Date() })
      .where(and(eq(discoveredSurfaces.surfaceId, res.surfaceId), eq(discoveredSurfaces.customerId, customerId)));
  }

  const result: SweepResult = {
    sweepId,
    surfacesReviewed: gateOutcome.totalSurfaces,
    surfacesRemediated: gateOutcome.accepted,
    issuesFound,
    durationMs: Date.now() - startTime,
  };

  await db.update(sweepTriggers)
    .set({
      status: blocked.length > 0 ? 'completed_with_blocks' : 'completed',
      surfacesReviewed: result.surfacesReviewed,
      surfacesRemediated: result.surfacesRemediated,
      durationMs: result.durationMs,
      completedAt: new Date(),
    })
    .where(eq(sweepTriggers.id, sweepId));

  log.info({
    customerId, sweepId,
    duration: result.durationMs,
    reviewed: result.surfacesReviewed,
    remediated: result.surfacesRemediated,
    issuesFound,
    blocked: blocked.length,
  }, 'Remediation sweep complete');

  return result;
}

